import {regularPayroll2026} from './payroll.js';
export const STRATEGIES=[['rurupMonthly','Your Rürup','Deduction and cash contribution'],['spouseRurupMonthly','Spouse Rürup','Deduction and cash contribution'],['depotMonthly','Your Altersvorsorgedepot','Contribution, allowance and favorable check'],['spouseDepotMonthly','Spouse Altersvorsorgedepot','Contribution, allowance and favorable check'],['privateMonthly','Your ordinary private pension','Cash contribution; no current deduction'],['spousePrivateMonthly','Spouse ordinary private pension','Cash contribution; no current deduction'],['otherDeductions','Other special deductions','Optional deduction above statutory allowances'],['payrollAllowance','Hypothetical payroll Freibetrag','Payroll preview only; never a second annual deduction']];
export const strategyOn=(s,key)=>s.strategies?.[key]!==false;
export const propertyOn=p=>p.enabled!==false;
export function guaranteeReady(p){const g=p.guaranteePlan;return !!(g?.enabled&&g.confirmed&&Number.isFinite(g.annualPremium)&&Number.isFinite(g.coveragePercent)&&Number.isInteger(g.startYear)&&Number.isInteger(g.endYear));}
/** Single selection boundary for all tax, cash, report and risk calculations. */
export function effectiveState(s){const h={...s.household};for(const [key] of STRATEGIES)if(key!=='payrollAllowance'&&!strategyOn(s,key))h[key]=0;if(!h.joint){h.spouseRurupMonthly=0;h.spouseDepotMonthly=0;h.spousePrivateMonthly=0;}const properties=s.properties.filter(propertyOn).map(p=>{const costs=p.costs.filter(c=>c.enabled!==false&&c.id!=='guarantee-'+p.id);if(guaranteeReady(p)){const g=p.guaranteePlan;costs.push({id:'guarantee-'+p.id,name:'Confirmed rent-guarantee premium',amount:g.annualPremium,frequency:'annual',from:g.startYear+'-01',to:g.endYear+'-12',type:'deductible',growth:0});}return {...p,costs};});return {...s,household:h,properties};}
export function scenarioPayroll(s,stages){const p=s.payroll;if(!p)return null;const baseActive=stages.some(v=>v.id===p.approvedPropertyId);if(!strategyOn(s,'payrollAllowance'))return regularPayroll2026({...p,annualAllowance:0,monthlyAllowance:0});const annualBase=baseActive?p.annualAllowance:0;const monthBase=baseActive?(p.monthlyAllowance??Math.ceil(annualBase/12)):0;const additional=stages.filter(v=>v.id!==p.approvedPropertyId).reduce((n,v)=>n+v.result,0);return regularPayroll2026({...p,annualAllowance:Math.max(0,annualBase-additional),monthlyAllowance:additional===0?monthBase:Math.ceil(Math.max(0,monthBase-additional/12))});}
